<script lang="ts">
 import { onMount, tick } from 'svelte';
 import { remoteLiveQuery as liveQuery } from '$lib/db/remote';
 import Portrait from '$lib/components/notebook/Portrait.svelte';
 import { chatStore } from '$lib/stores/chat.svelte';
 import { characterStore } from '$lib/stores/character.svelte';
 import { modulesStore } from '$lib/stores/modules.svelte';
 import { ttsStore } from '$lib/stores/tts.svelte';
 import { sendCompanionMessage, cancelActiveTurn, type SendCompanionMessageOptions } from '$lib/services/chat/companion-chat';
 import { startCompanionSession } from '$lib/services/session/companion-session';
 import { createEventSession } from '$lib/services/session/event-session.svelte';
 import { EventScene } from '$lib/components/events';
 import Toasts from '$lib/components/ui/Toasts.svelte';
 import { getFacts, saveFact } from '$lib/services/storage/memory';
 import { unlockAudioContext } from '$lib/services/tts';
 import type { Fact } from '$lib/types/memory';
 let draft=$state(''), facts=$state<Fact[]>([]), memoryDraft=$state(''), addingMemory=$state(false), savingMemory=$state(false), memoryError=$state('');
 let conversation=$state<HTMLDivElement>();
 let scrollFollow=$state(true);
 const events=createEventSession();
 const name=$derived(characterStore.name || 'Utsuwa');
 const ready=$derived(characterStore.isReady && modulesStore.isModuleEnabled('consciousness'));
 const voiced=$derived(modulesStore.isModuleEnabled('speech'));
 const stages: Record<string,string>={companion:'彼此陪伴',stranger:'初次相遇',acquaintance:'慢慢熟悉',friend:'心事朋友',close_friend:'亲密朋友',romantic_interest:'悄悄心动',dating:'恋爱日常',committed:'坚定相伴',soulmate:'灵魂伴侣'};
 const moods: Record<string,string>={happy:'今天心情很好',sad:'想要一点陪伴',excited:'有好多话想说',content:'此刻很安心',curious:'想多了解你一点',affectionate:'有一点想你',playful:'想和你开个玩笑',neutral:'在等你的消息'};
 const starters=[{icon:'☕',title:'雨天咖啡馆',line:'窗外下着雨，你把热咖啡推到我面前。我们聊聊今天吧。'},{icon:'☾',title:'深夜小纸条',line:'夜深了，有些白天没说出口的心事，我想慢慢讲给你听。'},{icon:'✿',title:'一起去散步',line:'傍晚的风很舒服，我们一起散步吧。你想和我聊些什么？'}];
 async function send(text: string, options?: SendCompanionMessageOptions){
  if(!ready || chatStore.isLoading || !text.trim())return;
  unlockAudioContext();draft='';scrollFollow=true;
  await sendCompanionMessage(text,[],{setTyping:()=>{},setLatestResponse:()=>{},setActiveEvent:events.open},{...options,mode:'text'});
 }
 function keydown(event: KeyboardEvent){if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();void send(draft);}}
 function toggleVoice(){unlockAudioContext();if(voiced)ttsStore.stop();void modulesStore.setModuleEnabled('speech',!voiced);}
 async function addMemory(){
  if(!memoryDraft.trim()||savingMemory)return;savingMemory=true;memoryError='';
  try{await saveFact({content:memoryDraft.trim(),category:'user',source:'用户手动记忆',importance:75});memoryDraft='';addingMemory=false;}
  catch{memoryError='这条记忆没有保存成功，请再试一次。';}finally{savingMemory=false;}
 }
 onMount(()=>{
  const stop=startCompanionSession({send:(text,options)=>void send(text,options),onEvent:events.open});
  const subscription=liveQuery(()=>getFacts({limit:5})).subscribe({next:value=>facts=value,error:()=>memoryError='暂时无法读取账号记忆。'});
  return ()=>{stop();subscription.unsubscribe();};
 });
 $effect(()=>{const last=chatStore.messages.at(-1)?.content;const count=chatStore.messages.length;const container=conversation;if(container&&scrollFollow){void tick().then(()=>{container.scrollTop=container.scrollHeight;});}});
</script>
<svelte:head><title>文字剧情 · 纸间</title><meta name="description" content="在一本小小的手绘日记里，和她聊天、书写剧情，记住属于你们的日常。"/></svelte:head>
<div class="notebook-page paper-world">
 <div class="page-heading"><div><p class="eyebrow">OUR LITTLE STORY / 一起写下的日常</p><h1>把今天，<span>慢慢讲给我听。</span><span class="heart" aria-hidden="true">♡</span></h1><p class="muted">不用很有趣，也不用很勇敢。你想说的，我都想听。</p></div><span class="day-stamp">{new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric'}).format(new Date())}<small>A PAGE OF US</small></span></div>
 <div class="notebook-grid">
  <aside class="companion-column">
   <section class="profile paper-card tape"><div class="portrait-frame"><Portrait/></div><div class="profile-name"><h2>{name}</h2><span class="tiny-heart" aria-hidden="true">♡</span></div><p class="mood"><i class="local-dot"></i>{moods[characterStore.state.mood.primary] || '想听听你的声音'}</p><div class="relationship"><span>我们的关系</span><strong>{stages[characterStore.state.relationshipStage] || '慢慢靠近'}</strong></div><div class="bond"><span>信任</span><progress max="100" value={characterStore.state.trust} aria-label="信任程度"></progress><small>{Math.round(characterStore.state.trust)}%</small></div><p class="profile-note">「故事可以换一种讲法，<br/>但我记得的你，还是你。」</p></section>
   <div class="scene-note"><span class="pin" aria-hidden="true">●</span><p class="eyebrow">TODAY'S CHAPTER</p><h3>日常，也值得被记住。</h3><p>一杯咖啡、一段散步，<br/>或者只是，说一句想你。</p><svg viewBox="0 0 150 36" aria-hidden="true"><path d="M5 10Q50 43 117 13L110 5M117 13L110 25" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-dasharray="5 5"/></svg></div>
  </aside>
  <main class="conversation-card paper-card">
   <header class="conversation-heading"><div><span class="eyebrow">CHAPTER 01</span><h2>你和她的故事</h2></div><button class="voice-button" class:enabled={voiced} onclick={toggleVoice} aria-pressed={voiced} title="切换角色回复语音">{voiced?'♪ 语音已开':'♪ 安静阅读'}</button></header>
   <div class="conversation" bind:this={conversation} onscroll={()=>{if(conversation)scrollFollow=conversation.scrollHeight-conversation.scrollTop-conversation.clientHeight<100;}} role="log" aria-label="对话记录" aria-live="polite" aria-relevant="additions">
    <div class="chapter-divider"><span>故事，从一句话开始</span></div>
    {#if !chatStore.messages.length}<div class="opening"><span class="opening-mark" aria-hidden="true">✳</span><p>她合上手里的书，抬头看向你。</p><div class="message assistant"><small>{name} · 开场白</small><p>你来啦。<br/>今天想从哪里说起？我在这里。</p></div></div>{/if}
    {#each chatStore.messages as message (message.id)}
     {#if message.role!=='system'}<div class="message-row" class:mine={message.role==='user'}><div class="message" class:assistant={message.role==='assistant'} class:user={message.role==='user'}><small>{message.role==='assistant'?name:'你'}<time datetime={new Date(message.timestamp).toISOString()}>{new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit'}).format(new Date(message.timestamp))}</time></small><p>{message.content || '正在把想说的话，写给你…'}</p></div></div>{/if}
    {/each}
    {#if chatStore.isLoading}<p class="writing" role="status">✎ 她正在认真地想……</p>{/if}
   </div>
   {#if chatStore.error}<div class="chat-error paper-error" role="alert">{chatStore.error}</div>{/if}
   <footer class="composer-area"><form onsubmit={(e)=>{e.preventDefault();void send(draft);}}><label class="sr-only" for="story-message">给她的消息</label><textarea id="story-message" bind:value={draft} onkeydown={keydown} placeholder={ready?'写点什么给她吧…':'正在翻开你们的故事…'} rows="2" maxlength="4000" disabled={!ready}></textarea><div class="composer-bottom"><span>Enter 发送 · Shift + Enter 换行</span>{#if chatStore.isLoading}<button type="button" class="paper-button" onclick={cancelActiveTurn}>停止回复</button>{:else}<button type="submit" class="paper-button primary" disabled={!ready || !draft.trim()}>寄给她 <span aria-hidden="true">↗</span></button>{/if}</div></form><p class="save-note">⌂ 服务器数据库保存 · 两种模式共享记忆 · 同一账号跨设备继续</p></footer>
  </main>
  <aside class="memory-column">
   <section class="memories"><div class="memory-title"><h2>她记得的小事</h2><span aria-hidden="true">✧</span></div><p class="muted memory-subtitle">关于你，一点一点收集。</p>
    {#if facts.length}{#each facts as fact,i}<article class="memory-note" style:--tilt={`${i%2?1.5:-1.5}deg`}><span class="note-number">0{i+1}</span><p>{fact.content}</p><span class="note-scribble" aria-hidden="true">♡</span></article>{/each}{:else}<article class="memory-note empty-memory"><span class="note-number">TO BE CONTINUED</span><p>这里还空着。<br/>下一张小纸条，<br/>也许就关于你。</p><span class="note-scribble" aria-hidden="true">♡</span></article>{/if}
    {#if addingMemory}<form class="memory-form" onsubmit={e=>{e.preventDefault();void addMemory();}}><label for="remember-me">想让她记住的事</label><textarea class="paper-input" id="remember-me" bind:value={memoryDraft} placeholder="例如：我喜欢下雨天和热拿铁。" maxlength="300" required></textarea><div><button class="ink-link" type="button" onclick={()=>addingMemory=false}>取消</button><button class="paper-button" type="submit" disabled={savingMemory}>{savingMemory?'保存中…':'记下来'}</button></div></form>{:else}<button class="add-memory" onclick={()=>addingMemory=true}>＋ 留一张关于我的纸条</button>{/if}
    {#if memoryError}<p class="paper-error" role="alert">{memoryError}</p>{/if}
   </section>
   <div class="shared-note"><span aria-hidden="true">↔</span><p>切到 3D，故事继续。<br/><small>同一个她，同一份记忆。</small></p></div><a class="ink-link memory-settings" href="/app/settings/memory">查看与管理记忆 ↗</a>
  </aside>
 </div>
 <Toasts/>
 {#if events.activeEvent&&(events.generatedScene||events.activeEvent.scene)}<EventScene scene={events.generatedScene||events.activeEvent.scene!} pending={events.pending} eventName={events.activeEvent.name} companionName={name} onComplete={events.complete} onClose={events.close}/>{/if}
</div>
<style>
