eg)}.pin{position:absolute;top:-11px;left:45%;color:var(--red);font-size:23px}.scene-note .eyebrow{font-size:10px}.scene-note h3{font-size:18px;margin:9px 0}.scene-note>p:not(.eyebrow){font-size:13px;color:#7a7367}.scene-note svg{width:130px;height:40px;color:var(--blue);margin:9px 0 0}.conversation-card{overflow:hidden;border-radius:10px 35px 15px 25px / 35px 10px 25px 15px;min-height:480px;height:calc(100dvh - 265px);display:flex;flex-direction:column;box-shadow:5px 5px 0 var(--ink)}.conversation-heading{padding:19px 25px 15px;border-bottom:1.5px dashed #cfc6b7;display:flex;align-items:center;justify-content:space-between}.conversation-heading .eyebrow{font-size:10px;letter-spacing:.18em}.conversation-heading h2{font-size:23px;margin-top:4px}.voice-button{border:1.5px solid #b4ac9c;border-radius:var(--wobble);padding:7px 11px;background:var(--paper);font-size:12px;color:#847a6a;min-height:36px}.voice-button.enabled{color:var(--blue);border-color:var(--blue);background:#f1f5fa}.conversation{padding:21px 26px;overflow-y:auto;flex:1;min-height:160px;scrollbar-width:thin;scrollbar-color:#d7cdbb transparent;overscroll-behavior:contain}.chapter-divider{display:flex;align-items:center;gap:15px;justify-content:center;font-size:11px;color:#9c9485;margin-bottom:26px}.chapter-divider:before,.chapter-divider:after{content:'';width:35px;border-top:1px dashed #b4ad9f}.opening>p{font-size:13px;color:#9b907e;text-align:center;margin:0 0 23px}.opening-mark{display:block;text-align:center;color:#bcab88;font-size:25px;margin:0 0 10px}.message-row{display:flex;margin:20px 0}.message-row.mine{justify-content:flex-end}.message{max-width:90%;border-radius:var(--wobble-md);padding:15px 19px;font-size:17px;line-height:1.9}.message.assistant{border:1.5px solid #d1c4af;background:#f7f2e8;box-shadow:2px 2px 0 #e5dac6}.message.user{background:#eaf0f7;border:1.5px solid #a8b8cb;transform:rotate(.3deg)}.message small{display:flex;gap:20px;justify-content:space-between;font-size:11px;color:#8a8172;margin-bottom:5px}.message.user small{color:#677a91}.message time{font-size:10px}.message p{white-space:pre-wrap;overflow-wrap:anywhere}.opening .message{max-width:85%;margin-bottom:15px}.writing{font-size:13px;color:var(--blue);padding:0 8px 10px}.composer-area{padding:15px 20px 12px;border-top:1.5px dashed #cfc6b7;background:#fffdf7}.composer-area form{border:2px solid var(--ink);border-radius:var(--wobble-md);padding:13px 15px 10px;background:white}.composer-area textarea{display:block;resize:none;min-height:60px;max-height:130px;background:transparent;color:var(--ink);border:none;width:100%;outline:none;font-size:17px;line-height:1.7}.composer-area textarea:focus-visible{outline:none}.composer-area form:focus-within{border-color:var(--blue)}.composer-area textarea::placeholder{color:#aaa18f}.composer-bottom{display:flex;align-items:center;justify-content:space-between;gap:10px}.composer-bottom>span{font-size:10px;color:#aaa18f}.composer-bottom .paper-button{min-height:38px;font-size:14px;padding:5px 15px}.save-note{text-align:center;font-size:10px;color:#a59b87;margin-top:11px!important;letter-spacing:.02em}.chat-error{margin:5px 20px 10px;font-size:12px}.memory-title{display:flex;justify-content:space-between;align-items:center}.memory-title h2{font-size:23px}.memory-title>span{font-size:30px;color:var(--blue)}.memory-subtitle{font-size:12px;margin:5px 0 24px!important}.memory-note{background:var(--yellow);border-radius:var(--wobble-md);padding:18px 18px 27px;position:relative;transform:rotate(var(--tilt,-2deg));margin-bottom:18px;box-shadow:3px 4px 0 #c9be9850;overflow-wrap:anywhere}.memory-note:nth-of-type(even){background:#f1e9da}.note-number{font-size:10px;letter-spacing:.1em;color:#a28f55}.memory-note p{font-size:15px;line-height:1.8;margin-top:8px}.note-scribble{position:absolute;right:15px;bottom:5px;color:#c5a944;font-size:24px}.empty-memory{padding-top:25px;padding-bottom:45px;min-height:195px}.add-memory{width:100%;padding:13px 8px;border:1.5px dashed #a99c81;border-radius:var(--wobble);background:transparent;color:#91856f;font-size:12px}.add-memory:hover{background:var(--yellow)}.memory-form{padding:13px;background:#fff9db;border:1.5px dashed #9b8f71;border-radius:var(--wobble-md);font-size:13px}.memory-form textarea{font-size:14px;resize:vertical;min-height:90px;margin:8px 0}.memory-form>div{display:flex;justify-content:space-between;gap:10px}.memory-form .paper-button{min-height:34px;padding:4px 11px;font-size:12px}.shared-note{display:flex;align-items:center;gap:12px;border-top:1.5px dashed #bfb5a3;margin-top:27px;padding:18px 3px 0;font-size:13px;color:#736b5d}.shared-note>span{font-size:27px;color:var(--blue)}.shared-note small{font-size:11px;color:#a09581}.memory-settings{display:inline-block;margin-top:15px;font-size:11px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
@media(min-width:1600px){.notebook-page{padding-top:40px}.notebook-grid{grid-template-columns:230px minmax(400px,1fr) 250px;gap:38px}.conversation-card{min-height:680px}}@media(max-width:1120px){.notebook-grid{grid-template-columns:180px minmax(320px,1fr);gap:22px}.memory-column{grid-column:1/-1;display:grid;grid-template-columns:1fr 180px;gap:20px}.memories{grid-row:span 2}.memory-note{display:inline-block;vertical-align:top;width:calc(50% - 15px);margin-right:15px}.memory-note.empty-memory{min-height:130px;width:100%}.conversation-card{height:calc(100dvh - 240px);min-height:480px}.day-stamp{display:none}.profile-name h2{font-size:21px}.bond{gap:6px}}@media(max-width:700px){.notebook-page{padding:20px 16px}.page-heading{margin-bottom:20px}.page-heading .eyebrow{font-size:10px}.page-heading h1{font-size:27px}.page-heading>div>.muted{font-size:12px}.heart{display:none}.notebook-grid{display:flex;flex-direction:column;gap:22px}.companion-column{display:none}.conversation-card{width:100%;min-height:380px;height:calc(100dvh - 245px)}.conversation-heading{padding:14px 16px}.conversation-heading h2{font-size:21px}.conversation{padding:18px 15px}.message{font-size:16px;padding:12px 15px;max-width:94%}.composer-area{padding:12px}.composer-area form{padding:10px 12px}.composer-bottom>span{font-size:9px}.composer-area textarea{font-size:16px}.memory-column{display:block;width:100%}.memory-title h2{font-size:22px}.memory-note{width:calc(50% - 9px);margin-right:9px}.memory-note p{font-size:14px}.shared-note,.memory-settings{display:none}.memory-form{margin-bottom:15px}.save-note{font-size:9px}}
